#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int m = r() % 3 + 1; std::vector<std::vector<int>> a(m); int vals = r() % 3 + 1; std::vector<int> all; for (int i = 0; i < m; i++) { int k = 2 * (r() % 2 + 1); a[i].resize(k); } int total = 0; for (auto& x : a) total += x.size(); std::vector<int> pool; for (int i = 0; i < total / 2; i++) { int x = r() % vals + 1; pool.push_back(x); pool.push_back(x); } std::shuffle(pool.begin(), pool.end(), r); int p = 0; printf("%d\n", m); for (auto& x : a) { printf("%d", (int)x.size()); for (size_t j = 0; j < x.size(); j++) printf(" %d", pool[p++]); puts(""); } }
